"""Automatic names are fixed at submission, not regenerated by retry."""
import json
from unittest.mock import patch
import test_edit_policy as edit_tests


class NamingSubmission(edit_tests.EditModeSubmissionTests):
    def test_name_comes_from_media_not_frontend_default(self):
        response=self.server.submit(dict(self.request,name='我的第一个剪辑项目',
            projectNaming={'projectName':'客户端伪造名称'}))
        saved=json.loads((self.root/'jobs'/response['id']/'input.json').read_text())
        naming=saved['projectNaming']
        self.assertNotIn('我的第一个剪辑项目',naming['projectName'])
        self.assertNotIn('客户端伪造',naming['projectName'])
        self.assertEqual(naming['timezone'],'Asia/Shanghai')
        from project_naming import make_project_naming
        self.assertEqual(naming,make_project_naming(saved['assets'],response['id'],response['created']))

    def test_duplicate_client_request_keeps_original_name(self):
        payload=dict(self.request,clientRequestId='fixed-name-request')
        first=self.server.submit(payload)
        path=self.root/'jobs'/first['id']/'input.json'
        original=path.read_bytes()
        with patch.object(self.server.time,'time',return_value=9999999999):
            second=self.server.submit(payload)
        self.assertEqual(first['id'],second['id'])
        self.assertEqual(original,path.read_bytes())
